head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.submission1_submitdone = function(e) {
    console.log("done1");
};
scwin.submission2_submitdone = function(e) {
    console.log("done2");
};
scwin.submission3_submitdone = function(e) {
    console.log("done3");
};
scwin.btnStatic_onclick = function(e) {
    scwin.$w.executeSubmission("submission1");
};
scwin.btnDynamic_onclick = function(e) {
    var submissionObj = {
        "id": "submission_dynamic0",
        "ref": "",
        "target": "data:json,dltList",
        "action": "submission_executeSubmission_WEFF-74_(WSQ-3134).json",
        "method": "get",
        "mediatype": "application/json",
        "encoding": "UTF-8",
        "mode": "asynchronous",
        "processMsg": "processing ~ ~ ~ ",
        "submitDoneHandler": "scwin.submission2_submitdone"
    };
    scwin.$w.createSubmission(submissionObj);
    scwin.$w.executeSubmission("submission_dynamic0");
};
scwin.__checkErrLog = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("undefined is not a function");
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnDynamic').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == '-1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
